//! P3 gate: greedy line recognition vs the Python reference (plan §P3).
//!
//! Per page: the Rust rec path (crop -> script routing -> 4-group recognizers
//! -> CTC collapse -> vocab decode, no LM) is run on the upright page, and
//! each line's (text, conf) is compared with the reference (generated by
//! scripts/gen-p3-reference.py from the actual indra-ocr product code with
//! the LM disabled to match this stage; the P4 gate re-runs with the LM).
//!
//! Judged (plan §P3):
//!   * line text EXACT match rate >= 95% over the 32 pages,
//!   * mean |conf difference| over all lines < 0.02.
//!
//! The winning group is reported per line as diagnostics (routing drift); it
//! is not a hard gate — two groups can legitimately produce the same reading.

use std::path::PathBuf;

use image::ImageReader;

use docs2md::l1::indra::preproc::Gray;
use docs2md::l1::indra::rec;
use docs2md::l1::indra::IndraEngine;

#[test]
fn p3_gate_32_pages() {
    let root = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/p1");
    let ref_dir = root.join("ref");
    let mut metas: Vec<PathBuf> = std::fs::read_dir(&ref_dir)
        .unwrap()
        .map(|e| e.unwrap().path())
        .filter(|p| {
            p.file_name()
                .unwrap()
                .to_string_lossy()
                .ends_with(".meta.json")
        })
        .collect();
    metas.sort();
    assert_eq!(metas.len(), 32, "32 reference pages");

    let mut engine = IndraEngine::init().expect("indra init");
    // P3 gate contract: compare the PURE GREEDY reading. The reference
    // (.rec.json, gen-p3) was generated by the product with LM disabled
    // (p.lms = {}).  P4 added inline LM beam re-read into rec::recognize,
    // which would corrupt this comparison — clear the loaded LMs so this
    // gate stays on the greedy path regardless of engine defaults.
    engine.lms.clear();
    let mut text_match = 0usize;
    let mut text_total = 0usize;
    let mut conf_deltas = Vec::new();
    let mut group_diff = 0usize;
    let mut bad_pages = Vec::new();

    for meta_path in &metas {
        let tag = meta_path.file_name().unwrap().to_string_lossy().to_string();
        let tag = &tag[..tag.len() - ".meta.json".len()];

        let meta: serde_json::Value =
            serde_json::from_str(&std::fs::read_to_string(meta_path).unwrap()).unwrap();
        let boxes: Vec<[f64; 4]> = meta["detect"]["boxes"]
            .as_array()
            .unwrap()
            .iter()
            .map(|b| {
                let a = b.as_array().unwrap();
                [
                    a[0].as_f64().unwrap(),
                    a[1].as_f64().unwrap(),
                    a[2].as_f64().unwrap(),
                    a[3].as_f64().unwrap(),
                ]
            })
            .collect();
        let rec_ref: serde_json::Value = serde_json::from_str(
            &std::fs::read_to_string(ref_dir.join(format!("{tag}.rec.json"))).unwrap(),
        )
        .unwrap();
        let ref_lines: Vec<(String, f64, String)> = rec_ref["lines"]
            .as_array()
            .unwrap()
            .iter()
            .map(|l| {
                (
                    l["text"].as_str().unwrap().to_string(),
                    l["conf"].as_f64().unwrap(),
                    l["group"].as_str().unwrap().to_string(),
                )
            })
            .collect();
        assert_eq!(boxes.len(), ref_lines.len(), "{tag}: line count mismatch");

        // Upright page (P1-gated) -> the full rec path.
        let upright = ImageReader::open(ref_dir.join(format!("{tag}.upright.png")))
            .unwrap()
            .decode()
            .unwrap()
            .into_luma8();
        let gray = Gray {
            w: upright.width() as usize,
            h: upright.height() as usize,
            data: upright.as_raw().to_vec(),
        };
        let lines = if boxes.is_empty() {
            Vec::new()
        } else {
            rec::recognize(&engine, &gray, &boxes)
        };

        let mut page_match = 0usize;
        for (i, l) in lines.iter().enumerate() {
            text_total += 1;
            let tm = l.text == ref_lines[i].0;
            if tm {
                text_match += 1;
                page_match += 1;
            }
            conf_deltas.push((l.conf as f64 - ref_lines[i].1).abs());
            if l.group != ref_lines[i].2 {
                group_diff += 1;
            }
            if !tm {
                eprintln!(
                    "{tag} line {i}: text mismatch\n  rust: {:?}\n  ref:  {:?} (conf rust {:.4} ref {:.4}, group {} vs {})",
                    l.text, ref_lines[i].0, l.conf, ref_lines[i].1, l.group, ref_lines[i].2
                );
            }
        }
        if page_match < ref_lines.len() {
            bad_pages.push(format!("{tag}: {}/{}", page_match, ref_lines.len()));
        }
    }

    let text_rate = text_match as f64 / text_total.max(1) as f64;
    let conf_mean: f64 = conf_deltas.iter().sum::<f64>() / conf_deltas.len().max(1) as f64;
    println!(
        "P3 gate: pages 32, lines {text_total}, text exact match {text_match}/{text_total} = {text_rate:.4} (>= 0.95 required), \
         conf mean |diff| {conf_mean:.5} (< 0.02 required), group diagnostics {group_diff} lines",
    );
    if !bad_pages.is_empty() {
        println!("  differing pages: {}", bad_pages.join(", "));
    }

    assert!(text_rate >= 0.95, "text exact match {text_rate:.4} < 0.95");
    assert!(conf_mean < 0.02, "conf mean |diff| {conf_mean:.5} >= 0.02");
}
